/**
 * Income Validation Schema
 * Yup validation untuk income transaction input
 */

import * as yup from 'yup'

export const createIncomeSchema = yup.object().shape({
  date: yup.date().required('Tanggal harus diisi').typeError('Format tanggal tidak valid'),
  typeId: yup
    .number()
    .required('Jenis pemasukan harus dipilih')
    .positive('Jenis pemasukan tidak valid'),
  sourceId: yup
    .number()
    .required('Sumber pemasukan harus dipilih')
    .positive('Sumber pemasukan tidak valid'),
  accountId: yup
    .number()
    .required('Akun harus dipilih')
    .positive('Akun tidak valid'),
  amount: yup
    .number()
    .required('Nominal harus diisi')
    .positive('Nominal harus lebih dari 0')
    .typeError('Nominal harus berupa angka'),
  note: yup.string().max(500, 'Catatan maksimal 500 karakter').optional(),
  assetId: yup.number().nullable().optional(),
})

export const updateIncomeSchema = createIncomeSchema.shape({
  id: yup.number().required().positive(),
})

export type CreateIncomeSchemaType = yup.InferType<typeof createIncomeSchema>
export type UpdateIncomeSchemaType = yup.InferType<typeof updateIncomeSchema>
