'use server'

import {
  createOutcome,
  getOutcomeList,
  getOutcomeById,
  updateOutcome,
  deleteOutcome,
} from '@/features/outcome/services/createOutcome'
import {
  createOutcomeSchema,
  updateOutcomeSchema,
} from '@/features/outcome/schemas/outcome.schema'
import {
  createSuccessResponse,
  createErrorResponse,
  createPaginatedResponse,
} from '@/types/response.type'
import { ValidationError } from 'yup'
import { OutcomeListQuery } from '@/features/outcome/types/outcome.type'

export async function getOutcomeListAction(query: {
  page?: number
  pageSize?: number
  startDate?: string
  endDate?: string
  accountId?: number
  categoryId?: number
}) {
  try {
    const parsedQuery: OutcomeListQuery = {
      page: query.page || 1,
      pageSize: query.pageSize || 10,
      startDate: query.startDate ? new Date(query.startDate) : undefined,
      endDate: query.endDate ? new Date(query.endDate) : undefined,
      accountId: query.accountId,
      categoryId: query.categoryId,
    }

    const { outcomes, total } = await getOutcomeList(parsedQuery)

    return createPaginatedResponse(outcomes, total, parsedQuery.page!, parsedQuery.pageSize!)
  } catch (error) {
    console.error('getOutcomeListAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch outcomes',
      'OUTCOME_FETCH_ERROR'
    )
  }
}

export async function getOutcomeByIdAction(id: number) {
  try {
    const outcome = await getOutcomeById(id)
    if (!outcome) {
      return createErrorResponse('Outcome not found', 'OUTCOME_NOT_FOUND')
    }
    return createSuccessResponse(outcome)
  } catch (error) {
    console.error('getOutcomeByIdAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch outcome',
      'OUTCOME_FETCH_ERROR'
    )
  }
}

export async function createOutcomeAction(input: any) {
  try {
    await createOutcomeSchema.validate(input, { abortEarly: false })

    const outcome = await createOutcome({
      date: new Date(input.date),
      categoryId: input.categoryId,
      subcategoryId: input.subcategoryId,
      accountId: input.accountId,
      amount: input.amount,
      note: input.note,
    })

    return createSuccessResponse(outcome, 'Outcome created successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('createOutcomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create outcome',
      'OUTCOME_CREATE_ERROR'
    )
  }
}

export async function updateOutcomeAction(input: any) {
  try {
    await updateOutcomeSchema.validate(input, { abortEarly: false })

    const outcome = await updateOutcome({
      id: input.id,
      date: input.date ? new Date(input.date) : undefined,
      categoryId: input.categoryId,
      subcategoryId: input.subcategoryId,
      accountId: input.accountId,
      amount: input.amount,
      note: input.note,
    })

    return createSuccessResponse(outcome, 'Outcome updated successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('updateOutcomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update outcome',
      'OUTCOME_UPDATE_ERROR'
    )
  }
}

export async function deleteOutcomeAction(id: number) {
  try {
    await deleteOutcome(id)
    return createSuccessResponse(null, 'Outcome deleted successfully')
  } catch (error) {
    console.error('deleteOutcomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to delete outcome',
      'OUTCOME_DELETE_ERROR'
    )
  }
}
