'use server'

import {
  createIncome,
  getIncomeList,
  getIncomeById,
  updateIncome,
  deleteIncome,
} from '@/features/income/services/createIncome'
import {
  createIncomeSchema,
  updateIncomeSchema,
} from '@/features/income/schemas/income.schema'
import {
  createSuccessResponse,
  createErrorResponse,
  createPaginatedResponse,
} from '@/types/response.type'
import { ValidationError } from 'yup'
import { IncomeListQuery } from '@/features/income/types/income.type'

export async function getIncomeListAction(query: {
  page?: number
  pageSize?: number
  startDate?: string
  endDate?: string
  accountId?: number
}) {
  try {
    const parsedQuery: IncomeListQuery = {
      page: query.page || 1,
      pageSize: query.pageSize || 10,
      startDate: query.startDate ? new Date(query.startDate) : undefined,
      endDate: query.endDate ? new Date(query.endDate) : undefined,
      accountId: query.accountId,
    }

    const { incomes, total } = await getIncomeList(parsedQuery)

    return createPaginatedResponse(incomes, total, parsedQuery.page!, parsedQuery.pageSize!)
  } catch (error) {
    console.error('getIncomeListAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch incomes',
      'INCOME_FETCH_ERROR'
    )
  }
}

export async function getIncomeByIdAction(id: number) {
  try {
    const income = await getIncomeById(id)
    if (!income) {
      return createErrorResponse('Income not found', 'INCOME_NOT_FOUND')
    }
    return createSuccessResponse(income)
  } catch (error) {
    console.error('getIncomeByIdAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch income',
      'INCOME_FETCH_ERROR'
    )
  }
}

export async function createIncomeAction(input: any) {
  try {
    await createIncomeSchema.validate(input, { abortEarly: false })

    const income = await createIncome({
      date: new Date(input.date),
      typeId: input.typeId,
      sourceId: input.sourceId,
      accountId: input.accountId,
      amount: input.amount,
      note: input.note,
    })

    return createSuccessResponse(income, 'Income created successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('createIncomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create income',
      'INCOME_CREATE_ERROR'
    )
  }
}

export async function updateIncomeAction(input: any) {
  try {
    await updateIncomeSchema.validate(input, { abortEarly: false })

    const income = await updateIncome({
      id: input.id,
      date: input.date ? new Date(input.date) : undefined,
      typeId: input.typeId,
      sourceId: input.sourceId,
      accountId: input.accountId,
      amount: input.amount,
      note: input.note,
    })

    return createSuccessResponse(income, 'Income updated successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('updateIncomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update income',
      'INCOME_UPDATE_ERROR'
    )
  }
}

export async function deleteIncomeAction(id: number) {
  try {
    await deleteIncome(id)
    return createSuccessResponse(null, 'Income deleted successfully')
  } catch (error) {
    console.error('deleteIncomeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to delete income',
      'INCOME_DELETE_ERROR'
    )
  }
}
