/**
 * Trade Validation Schema
 * Yup validation untuk investment trade input
 */

import * as yup from 'yup'

export const createTradeSchema = yup.object().shape({
  date: yup.date().required('Tanggal harus diisi').typeError('Format tanggal tidak valid'),
  accountId: yup
    .number()
    .required('Akun harus dipilih')
    .positive('Akun tidak valid'),
  assetId: yup
    .number()
    .required('Asset harus dipilih')
    .positive('Asset tidak valid'),
  type: yup
    .string()
    .required('Tipe trade harus dipilih')
    .oneOf(['BUY', 'SELL'], 'Tipe trade harus BUY atau SELL'),
  quantity: yup
    .number()
    .required('Quantity harus diisi')
    .positive('Quantity harus lebih dari 0'),
  price: yup
    .number()
    .required('Price harus diisi')
    .positive('Price harus lebih dari 0'),
  fee: yup
    .number()
    .min(0, 'Fee tidak boleh negatif')
    .optional(),
  feeCurrency: yup.string().optional(),
  total: yup
    .number()
    .required('Total harus diisi')
    .positive('Total harus lebih dari 0'),
  note: yup.string().max(500, 'Catatan maksimal 500 karakter').optional(),
})

export const updateTradeSchema = createTradeSchema.shape({
  id: yup.number().required().positive(),
})

export type CreateTradeSchemaType = yup.InferType<typeof createTradeSchema>
export type UpdateTradeSchemaType = yup.InferType<typeof updateTradeSchema>
