'use server'

import { createLedgerEntryTx, getLedgerEntries } from './services/createLedgerEntry'
import { CreateLedgerEntryInput, LedgerListQuery } from './types/ledger.type'
import { createSuccessResponse, createErrorResponse } from '@/types/response.type'
import { createLedgerSchema } from './schemas/ledger.schema'
import { ValidationError } from 'yup'

export async function createLedgerAction(input: CreateLedgerEntryInput) {
  try {
    await createLedgerSchema.validate(input, { abortEarly: false })
    const entry = await createLedgerEntryTx(input)
    return createSuccessResponse(entry)
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('createLedgerAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create ledger entry',
      '500'
    )
  }
}

export async function getLedgerListAction(query: LedgerListQuery) {
  try {
    const data = await getLedgerEntries(query)
    return createSuccessResponse(data)
  } catch (error) {
    console.error('getLedgerListAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to get ledger entries',
      '500'
    )
  }
}
