/**
 * Account Services
 * Business logic untuk account management
 */

import { prisma } from '@/lib/prisma'
import { Account, AccountType, AccountBucket } from '@prisma/client'
import { CreateAccountInput, UpdateAccountInput, AccountSummary } from '../types/account.type'
import { toDecimal, toNumber } from '@/lib/db'

/**
 * Get all accounts dengan optional filter
 */
export async function getAccounts(filters?: {
  bucket?: AccountBucket
  type?: AccountType
  isActive?: boolean
  includeLedger?: boolean
}): Promise<any[]> {
  return prisma.account.findMany({
    where: {
      bucket: filters?.bucket,
      type: filters?.type,
      isActive: filters?.isActive,
    },
    include: filters?.includeLedger ? { ledgerEntries: { orderBy: { date: 'desc' } } } : undefined,
    orderBy: { name: 'asc' },
  })
}

/**
 * Get single account by ID
 */
export async function getAccountById(accountId: number): Promise<Account | null> {
  return prisma.account.findUnique({
    where: { id: accountId },
  })
}

/**
 * Create new account dengan optional initial balance
 */
export async function createAccount(input: CreateAccountInput): Promise<Account> {
  const account = await prisma.account.create({
    data: {
      name: input.name,
      type: input.type,
      bucket: input.bucket,
      currency: input.currency,
      balance: toDecimal(input.initialBalance || 0),
      isActive: true,
      supportedClasses: input.supportedClasses || "",
    },
  })

  return account
}

/**
 * Update account details
 */
export async function updateAccount(input: UpdateAccountInput): Promise<Account> {
  return prisma.account.update({
    where: { id: input.id },
    data: {
      name: input.name,
      currency: input.currency,
      isActive: input.isActive,
      supportedClasses: input.supportedClasses,
    },
  })
}

/**
 * Update account balance (internal use only)
 */
export async function updateAccountBalance(
  accountId: number,
  amount: number,
  direction: 'DEBIT' | 'CREDIT'
): Promise<Account> {
  const account = await getAccountById(accountId)
  if (!account) throw new Error(`Account ${accountId} not found`)

  const currentBalance = toNumber(account.balance)
  const newBalance =
    direction === 'CREDIT' ? currentBalance + amount : currentBalance - amount

  if (account.bucket !== 'LIABILITY' && newBalance < 0) {
    throw new Error(`Insufficient balance in account ${account.name}`)
  }

  if (account.bucket === 'LIABILITY' && newBalance > 0) {
    throw new Error(`Nominal pembayaran melebihi sisa outstanding utang pada akun ${account.name}`)
  }

  return prisma.account.update({
    where: { id: accountId },
    data: { balance: toDecimal(newBalance) },
  })
}

/**
 * Get summary dari semua akun
 */
export async function getAccountSummary(): Promise<AccountSummary> {
  const accounts = await getAccounts()

  const summary: AccountSummary = {
    total: 0,
    byBucket: { CASHFLOW: 0, SAVING: 0, INVESTMENT: 0, LIABILITY: 0 },
    byType: { CASH: 0, BANK: 0, E_WALLET: 0, E_MONEY: 0, INVESTMENT: 0, LIABILITY: 0 },
    byCurrency: {},
  }

  for (const account of accounts) {
    const balance = toNumber(account.balance)
    summary.total += balance
    summary.byBucket[account.bucket as AccountBucket] += balance
    summary.byType[account.type as AccountType] += balance

    if (!summary.byCurrency[account.currency]) {
      summary.byCurrency[account.currency] = 0
    }
    summary.byCurrency[account.currency] += balance
  }

  return summary
}

/**
 * Deactivate account (soft delete)
 */
export async function deactivateAccount(accountId: number): Promise<Account> {
  return prisma.account.update({
    where: { id: accountId },
    data: { isActive: false },
  })
}
