'use server'

import {
  createTransfer,
  getTransferList,
  getTransferById,
  updateTransfer,
  deleteTransfer,
} from '@/features/transfer/services/createTransfer'
import {
  createTransferSchema,
  updateTransferSchema,
} from '@/features/transfer/schemas/transfer.schema'
import {
  createSuccessResponse,
  createErrorResponse,
  createPaginatedResponse,
} from '@/types/response.type'
import { ValidationError } from 'yup'

export async function getTransferListAction(query: {
  page?: number
  pageSize?: number
  startDate?: string
  endDate?: string
  fromAccountId?: number
  toAccountId?: number
}) {
  try {
    const parsedQuery = {
      page: query.page || 1,
      pageSize: query.pageSize || 10,
      startDate: query.startDate ? new Date(query.startDate) : undefined,
      endDate: query.endDate ? new Date(query.endDate) : undefined,
      fromAccountId: query.fromAccountId,
      toAccountId: query.toAccountId,
    }

    const { transfers, total } = await getTransferList(parsedQuery)

    return createPaginatedResponse(transfers, total, parsedQuery.page!, parsedQuery.pageSize!)
  } catch (error) {
    console.error('getTransferListAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch transfers',
      'TRANSFER_FETCH_ERROR'
    )
  }
}

export async function getTransferByIdAction(id: number) {
  try {
    const transfer = await getTransferById(id)
    if (!transfer) {
      return createErrorResponse('Transfer not found', 'TRANSFER_NOT_FOUND')
    }
    return createSuccessResponse(transfer)
  } catch (error) {
    console.error('getTransferByIdAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch transfer',
      'TRANSFER_FETCH_ERROR'
    )
  }
}

export async function createTransferAction(input: any) {
  try {
    await createTransferSchema.validate(input, { abortEarly: false })

    const transfer = await createTransfer({
      date: new Date(input.date),
      fromAccountId: input.fromAccountId,
      toAccountId: input.toAccountId,
      amount: input.amount,
      feeFixed: input.feeFixed,
      feePercent: input.feePercent,
      note: input.note,
    })

    return createSuccessResponse(transfer, 'Transfer created successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('createTransferAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create transfer',
      'TRANSFER_CREATE_ERROR'
    )
  }
}

export async function updateTransferAction(input: any) {
  try {
    await updateTransferSchema.validate(input, { abortEarly: false })

    const transfer = await updateTransfer({
      id: input.id,
      date: input.date ? new Date(input.date) : undefined,
      fromAccountId: input.fromAccountId,
      toAccountId: input.toAccountId,
      amount: input.amount,
      feeFixed: input.feeFixed,
      feePercent: input.feePercent,
      note: input.note,
    })

    return createSuccessResponse(transfer, 'Transfer updated successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('updateTransferAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update transfer',
      'TRANSFER_UPDATE_ERROR'
    )
  }
}

export async function deleteTransferAction(id: number) {
  try {
    await deleteTransfer(id)
    return createSuccessResponse(null, 'Transfer deleted successfully')
  } catch (error) {
    console.error('deleteTransferAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to delete transfer',
      'TRANSFER_DELETE_ERROR'
    )
  }
}
