'use server'

import {
  getAccounts,
  getAccountById,
  createAccount,
  updateAccount,
  deactivateAccount,
  getAccountSummary,
} from '@/features/account/services/getAccounts'
import {
  createAccountSchema,
  updateAccountSchema,
} from '@/features/account/schemas/account.schema'
import {
  createSuccessResponse,
  createErrorResponse,
} from '@/types/response.type'
import { ValidationError } from 'yup'
import { AccountBucket, AccountType } from '@prisma/client'

export async function getAccountsAction(query?: {
  bucket?: AccountBucket | string
  type?: AccountType | string
  isActive?: boolean
  includeLedger?: boolean
}) {
  try {
    const accounts = await getAccounts({
      bucket: query?.bucket as AccountBucket,
      type: query?.type as AccountType,
      isActive: query?.isActive,
      includeLedger: query?.includeLedger,
    })
    return createSuccessResponse(accounts)
  } catch (error) {
    console.error('getAccountsAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch accounts',
      'ACCOUNT_FETCH_ERROR'
    )
  }
}

export async function getAccountByIdAction(id: number) {
  try {
    const account = await getAccountById(id)
    if (!account) {
      return createErrorResponse('Account not found', 'ACCOUNT_NOT_FOUND')
    }
    return createSuccessResponse(account)
  } catch (error) {
    console.error('getAccountByIdAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch account',
      'ACCOUNT_FETCH_ERROR'
    )
  }
}

export async function createAccountAction(input: any) {
  try {
    await createAccountSchema.validate(input, { abortEarly: false })
    const account = await createAccount({
      name: input.name,
      type: input.type,
      bucket: input.bucket,
      currency: input.currency,
      initialBalance: input.initialBalance,
      supportedClasses: input.supportedClasses,
    })
    return createSuccessResponse(account, 'Account created successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('createAccountAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create account',
      'ACCOUNT_CREATE_ERROR'
    )
  }
}

export async function updateAccountAction(input: any) {
  try {
    await updateAccountSchema.validate(input, { abortEarly: false })
    const account = await updateAccount({
      id: input.id,
      name: input.name,
      currency: input.currency,
      isActive: input.isActive,
      supportedClasses: input.supportedClasses,
    })
    return createSuccessResponse(account, 'Account updated successfully')
  } catch (error) {
    if (error instanceof ValidationError) {
      return createErrorResponse(
        'Validation failed',
        'VALIDATION_ERROR',
        error.inner.map((err) => ({ path: err.path, message: err.message }))
      )
    }
    console.error('updateAccountAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update account',
      'ACCOUNT_UPDATE_ERROR'
    )
  }
}

export async function deleteAccountAction(id: number) {
  try {
    const account = await deactivateAccount(id)
    return createSuccessResponse(account, 'Account deactivated successfully')
  } catch (error) {
    console.error('deleteAccountAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to deactivate account',
      'ACCOUNT_DELETE_ERROR'
    )
  }
}

export async function getAccountSummaryAction() {
  try {
    const summary = await getAccountSummary()
    return createSuccessResponse(summary)
  } catch (error) {
    console.error('getAccountSummaryAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch account summary',
      'ACCOUNT_SUMMARY_ERROR'
    )
  }
}
