'use server'

import { prisma } from "@/lib/prisma";
import { createSuccessResponse, createErrorResponse } from "@/types/response.type";

export async function getChatHistoryAction() {
  try {
    const messages = await prisma.chatMessage.findMany({
      orderBy: { createdAt: "asc" },
    });
    return createSuccessResponse(messages);
  } catch (error) {
    console.error("getChatHistoryAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to fetch chat history",
      "CHAT_FETCH_ERROR"
    );
  }
}

export async function saveChatMessageAction(role: "user" | "assistant" | string, text: string) {
  try {
    if (!role || !text) {
      return createErrorResponse("Role and text are required", "MISSING_FIELDS");
    }

    const created = await prisma.chatMessage.create({
      data: { role, text },
    });
    return createSuccessResponse(created);
  } catch (error) {
    console.error("saveChatMessageAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to save chat message",
      "CHAT_CREATE_ERROR"
    );
  }
}

export async function clearChatHistoryAction() {
  try {
    await prisma.chatMessage.deleteMany();
    return createSuccessResponse(null, "Chat history cleared");
  } catch (error) {
    console.error("clearChatHistoryAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to clear chat history",
      "CHAT_DELETE_ERROR"
    );
  }
}

export async function generateGeminiResponseAction(formattedContents: any[], systemInstruction: any) {
  try {
    const API_KEY = process.env.GEMINI_API_KEY;
    const BASE_URL = process.env.GEMINI_BASE_URL;
    const MODELS_RAW = process.env.GEMINI_MODELS;

    if (!API_KEY || !BASE_URL || !MODELS_RAW) {
      return createErrorResponse("Incomplete AI configuration on the server. Please fill in the .env file (GEMINI_API_KEY, GEMINI_BASE_URL, GEMINI_MODELS).", "ENV_ERROR");
    }

    const MODELS = MODELS_RAW.split(",");

    let resultText = "";
    let success = false;

    for (const model of MODELS) {
      try {
        const response = await fetch(
          `${BASE_URL}/models/${model}:generateContent?key=${API_KEY}`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              contents: formattedContents,
              systemInstruction,
              generationConfig: {
                temperature: 0.7,
                maxOutputTokens: 2048,
              },
            }),
          }
        );

        const data = await response.json();

        if (data.candidates && data.candidates[0]?.content?.parts[0]?.text) {
          resultText = data.candidates[0].content.parts[0].text;
          success = true;
          break;
        } else {
          console.warn(`Model ${model} failed or hit limit.`, data.error || data);
        }
      } catch (err) {
        console.error(`Connection failed to model ${model}:`, err);
      }
    }

    if (!success) {
      return createErrorResponse("Gemini models exhausted or unavailable", "GEMINI_ERROR");
    }

    return createSuccessResponse(resultText);
  } catch (error) {
    console.error("generateGeminiResponseAction error:", error);
    return createErrorResponse(error instanceof Error ? error.message : "Internal Server Error", "SERVER_ERROR");
  }
}
