/**
 * Outcome Services
 * Business logic untuk outcome management
 */

import { prisma } from '@/lib/prisma'
import { Outcome } from '@prisma/client'
import { CreateOutcomeInput, UpdateOutcomeInput, OutcomeListQuery, OutcomeSummary } from '../types/outcome.type'
import { createOutcomeSchema, updateOutcomeSchema } from '@/features/outcome/schemas/outcome.schema'
import { toDecimal, toNumber } from '@/lib/db'
import { createLedgerEntryTx } from '@/features/ledger/services/createLedgerEntry'
import { getAccountById } from '@/features/account/services/getAccounts'

/**
 * Create new outcome dengan automatic ledger entry
 */
export async function createOutcome(input: CreateOutcomeInput): Promise<Outcome> {
  // Validate input
  await createOutcomeSchema.validate(input, { abortEarly: false })

  // Get account to determine currency
  const account = await getAccountById(input.accountId)
  if (!account) throw new Error(`Account ${input.accountId} not found`)

  // Create outcome record
  const outcome = await prisma.outcome.create({
    data: {
      date: input.date,
      categoryId: input.categoryId,
      subcategoryId: input.subcategoryId,
      accountId: input.accountId,
      amount: toDecimal(input.amount),
      note: input.note,
    },
  })

  // Create ledger entry (DEBIT)
  await createLedgerEntryTx({
    accountId: input.accountId,
    direction: 'DEBIT',
    amount: input.amount,
    currency: account.currency,
    refType: 'OUTCOME',
    refId: outcome.id,
    note: `Outcome: ${outcome.note || 'N/A'}`,
  })

  return outcome
}

/**
 * Get outcome list dengan pagination dan filter
 */
export async function getOutcomeList(
  query: OutcomeListQuery
): Promise<{ outcomes: Outcome[]; total: number }> {
  const page = query.page || 1
  const pageSize = query.pageSize || 10
  const skip = (page - 1) * pageSize

  const outcomes = await prisma.outcome.findMany({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
      categoryId: query.categoryId,
    },
    orderBy: { date: 'desc' },
    skip,
    take: pageSize,
  })

  const total = await prisma.outcome.count({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
      categoryId: query.categoryId,
    },
  })

  return { outcomes, total }
}

/**
 * Get outcome by ID
 */
export async function getOutcomeById(outcomeId: number): Promise<Outcome | null> {
  return prisma.outcome.findUnique({
    where: { id: outcomeId },
  })
}

/**
 * Get outcome summary breakdown by category
 */
export async function getOutcomeSummary(
  query: OutcomeListQuery
): Promise<OutcomeSummary> {
  const outcomes = await prisma.outcome.findMany({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
    },
  })

  let totalOutcome = 0
  const byCategoryBreakdown: Record<string, number> = {}

  for (const outcome of outcomes) {
    const amount = toNumber(outcome.amount)
    totalOutcome += amount

    const catKey = outcome.categoryId.toString()
    if (!byCategoryBreakdown[catKey]) byCategoryBreakdown[catKey] = 0
    byCategoryBreakdown[catKey] += amount
  }

  const transactionCount = outcomes.length
  const averageTransaction = transactionCount > 0 ? totalOutcome / transactionCount : 0
  const account = query.accountId ? await getAccountById(query.accountId) : null

  return {
    totalOutcome,
    transactionCount,
    averageTransaction,
    byCategoryBreakdown,
    currency: account?.currency || 'IDR',
  }
}

/**
 * Delete outcome dan reverse ledger entry
 */
export async function deleteOutcome(outcomeId: number): Promise<void> {
  const outcome = await getOutcomeById(outcomeId)
  if (!outcome) throw new Error(`Outcome ${outcomeId} not found`)

  // Delete ledger entry
  await prisma.ledgerEntry.deleteMany({
    where: {
      refType: 'OUTCOME',
      refId: outcome.id,
    },
  })

  // Rebuild account balance
  await prisma.account.update({
    where: { id: outcome.accountId },
    data: { balance: await rebuildAccountBalanceFromLedger(outcome.accountId) },
  })

  // Delete outcome
  await prisma.outcome.delete({
    where: { id: outcomeId },
  })
}

export async function updateOutcome(input: UpdateOutcomeInput): Promise<Outcome> {
  await updateOutcomeSchema.validate(input, { abortEarly: false })

  const existing = await getOutcomeById(input.id)
  if (!existing) throw new Error(`Outcome ${input.id} not found`)

  const updated = await prisma.outcome.update({
    where: { id: input.id },
    data: {
      date: input.date,
      categoryId: input.categoryId,
      subcategoryId: input.subcategoryId,
      accountId: input.accountId,
      amount: toDecimal(input.amount),
      note: input.note,
    },
  })

  // rebuild ledger entries
  await prisma.ledgerEntry.deleteMany({ where: { refType: 'OUTCOME', refId: updated.id } })

  const account = await getAccountById(updated.accountId)
  if (!account) throw new Error(`Account ${updated.accountId} not found`)

  await createLedgerEntryTx({
    accountId: updated.accountId,
    direction: 'DEBIT',
    amount: toNumber(updated.amount),
    currency: account.currency,
    refType: 'OUTCOME',
    refId: updated.id,
    note: `Outcome: ${updated.note || 'N/A'}`,
  })

  if (existing.accountId !== updated.accountId) {
    await prisma.account.update({
      where: { id: existing.accountId },
      data: { balance: await rebuildAccountBalanceFromLedger(existing.accountId) },
    })
  }
  await prisma.account.update({
    where: { id: updated.accountId },
    data: { balance: await rebuildAccountBalanceFromLedger(updated.accountId) },
  })

  return updated
}

/**
 * Helper: rebuild balance dari ledger
 */
async function rebuildAccountBalanceFromLedger(accountId: number): Promise<any> {
  const entries = await prisma.ledgerEntry.findMany({
    where: { accountId },
  })

  let balance = 0
  for (const entry of entries) {
    const amount = toNumber(entry.amount)
    balance = entry.direction === 'CREDIT' ? balance + amount : balance - amount
  }

  return toDecimal(balance)
}
