'use server'

import {
  getTrades,
  getPositions,
  createTrade,
  findOrCreateAsset,
  getYieldCalendar,
  recordYieldPayout,
} from '@/features/investment/services'
import {
  createSuccessResponse,
  createErrorResponse,
} from '@/types/response.type'
import { prisma } from '@/lib/prisma'

export async function getTradesAction(accountId?: number) {
  try {
    const trades = await prisma.investmentTrade.findMany({
      where: accountId ? { accountId } : undefined,
      include: { asset: true, account: true },
      orderBy: { date: 'asc' },
    })

    const assetState: Record<string, { qty: number; cost: number }> = {}

    const rows = trades.map((t: any) => {
      const assetId = t.assetId
      const isGeneric = t.asset?.symbol === 'GENERIC'
      
      let pnl = 0
      const qty = Number(t.quantity)
      const total = Number(t.total)
      const fee = Number(t.fee || 0)
      const price = Number(t.price)
      let avgBuyPrice = 0

      if (isGeneric) {
        pnl = total - qty - fee
      } else {
        const stateKey = `${t.accountId}_${assetId}`
        if (!assetState[stateKey]) {
          assetState[stateKey] = { qty: 0, cost: 0 }
        }
        const state = assetState[stateKey]

        if (t.type === 'BUY') {
          state.qty += qty
          state.cost += total
          pnl = 0 
          avgBuyPrice = state.qty > 0 ? state.cost / state.qty : price
        } else {
          avgBuyPrice = state.qty > 0 ? state.cost / state.qty : 0
          pnl = total - (avgBuyPrice * qty) - fee
          
          state.qty = Math.max(0, state.qty - qty)
          state.cost = Math.max(0, state.cost - (avgBuyPrice * qty))
          if (state.qty === 0) {
            state.cost = 0
          }
        }
      }

      return {
        id: String(t.id),
        accountId: String(t.accountId),
        accountName: t.account?.name || 'Internal',
        tanggal: t.date.toISOString().split('T')[0],
        jumlahAwal: qty,
        jumlahAkhir: total,
        fee,
        pnl,
        avgBuyPrice,
        catatan: t.note || '',
        asset: t.asset?.symbol || '',
        class: t.asset?.class || 'STOCK',
        type: t.type,
        currency: t.account?.currency || 'USD',
      }
    })

    rows.reverse()

    return createSuccessResponse(rows)
  } catch (error) {
    console.error('getTradesAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch trades',
      'TRADES_FETCH_ERROR'
    )
  }
}

export async function getPositionsAction(accountId?: number) {
  try {
    const positions = accountId
      ? await prisma.investmentPosition.findMany({
          where: { accountId },
          include: {
            asset: {
              include: {
                yieldConfig: true,
                trades: {
                  orderBy: { date: 'asc' },
                },
              },
            },
          },
        })
      : await prisma.investmentPosition.findMany({
          include: {
            asset: {
              include: {
                yieldConfig: true,
                trades: {
                  orderBy: { date: 'asc' },
                },
              },
            },
          },
        })

    const rows = positions.map((p: any) => {
      const buyTrade = p.asset?.trades?.find(
        (t: any) => t.accountId === p.accountId && t.type === 'BUY'
      )
      return {
        id: String(p.id),
        accountId: String(p.accountId),
        assetId: p.assetId,
        symbol: p.asset?.symbol || '',
        nama: p.asset?.name || '',
        class: p.asset?.class || 'STOCK',
        quantity: Number(p.quantity),
        avgPrice: Number(p.avgPrice),
        tanggal: buyTrade
          ? buyTrade.date.toISOString().split('T')[0]
          : p.updatedAt
          ? p.updatedAt.toISOString().split('T')[0]
          : new Date().toISOString().split('T')[0],
        catatan: buyTrade?.note || '',
        yieldConfig: p.asset?.yieldConfig
          ? {
              rate: Number(p.asset.yieldConfig.rate),
              frequency: p.asset.yieldConfig.frequency,
              maturityDate: p.asset.yieldConfig.maturityDate
                ? p.asset.yieldConfig.maturityDate.toISOString().split('T')[0]
                : null,
              startDate: p.asset.yieldConfig.startDate.toISOString().split('T')[0],
              payoutDay: p.asset.yieldConfig.payoutDay,
              principal: p.asset.yieldConfig.principal
                ? Number(p.asset.yieldConfig.principal)
                : null,
              targetAccountId: p.asset.yieldConfig.targetAccountId,
            }
          : null,
      }
    })

    return createSuccessResponse(rows)
  } catch (error) {
    console.error('getPositionsAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch positions',
      'POSITIONS_FETCH_ERROR'
    )
  }
}

export async function createTradeAction(input: any) {
  try {
    if (!input.accountId || (!input.jumlahAwal && !input.quantity) || (!input.jumlahAkhir && !input.total)) {
      return createErrorResponse('Missing required fields', 'MISSING_FIELDS')
    }

    const assetSymbol = input.symbol || 'GENERIC'
    const assetName = input.nama || assetSymbol
    
    const account = await prisma.account.findUnique({
      where: { id: typeof input.accountId === 'string' ? parseInt(input.accountId) : input.accountId },
    })
    const baseCurrency = account?.currency || 'USD'
    const assetClass = input.class || (assetSymbol === 'GENERIC' ? 'OTHER' : 'STOCK')

    const asset = await findOrCreateAsset(assetSymbol, assetName, assetClass, baseCurrency)

    const quantity = input.jumlahAwal ? Number(input.jumlahAwal) : Number(input.quantity)
    const total = input.jumlahAkhir ? Number(input.jumlahAkhir) : Number(input.total)
    const fee = Number(input.fee || 0)
    const type = input.type || (total >= quantity ? 'SELL' : 'BUY')

    const tradeInput = {
      accountId: typeof input.accountId === 'string' ? parseInt(input.accountId) : input.accountId,
      assetId: asset.id,
      type: type as 'BUY' | 'SELL',
      quantity,
      price: input.price ? Number(input.price) : (quantity !== 0 ? total / quantity : 0),
      fee,
      total,
      date: input.tanggal ? new Date(input.tanggal) : (input.date ? new Date(input.date) : new Date()),
      note: input.catatan || input.note,
    }

    const trade = await createTrade(tradeInput)
    return createSuccessResponse(trade, 'Trade recorded')
  } catch (error) {
    console.error('createTradeAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create trade',
      'TRADE_CREATE_ERROR'
    )
  }
}

export async function createPositionAction(input: any) {
  try {
    if (!input.accountId || !input.symbol || !input.quantity || !input.avgPrice) {
      return createErrorResponse('Missing required fields', 'MISSING_FIELDS')
    }

    const account = await prisma.account.findUnique({
      where: { id: typeof input.accountId === 'string' ? parseInt(input.accountId) : input.accountId },
    })
    const baseCurrency = account?.currency || 'USD'
    const assetClass = input.class || 'STOCK'

    const asset = await findOrCreateAsset(input.symbol, input.nama, assetClass, baseCurrency)

    // Handle yield config if provided
    if (input.yieldRate && input.yieldFrequency) {
      const targetAccId = input.yieldTargetAccountId
        ? (typeof input.yieldTargetAccountId === 'string' ? parseInt(input.yieldTargetAccountId) : input.yieldTargetAccountId)
        : (typeof input.accountId === 'string' ? parseInt(input.accountId) : input.accountId);

      await prisma.assetYieldConfig.upsert({
        where: { assetId: asset.id },
        update: {
          rate: Number(input.yieldRate),
          frequency: input.yieldFrequency,
          maturityDate: input.yieldMaturityDate ? new Date(input.yieldMaturityDate) : null,
          startDate: input.date ? new Date(input.date) : new Date(),
          payoutDay: Number(input.yieldPayoutDay || 15),
          principal: Number(input.quantity) * Number(input.avgPrice),
          targetAccountId: targetAccId,
        },
        create: {
          assetId: asset.id,
          rate: Number(input.yieldRate),
          frequency: input.yieldFrequency,
          maturityDate: input.yieldMaturityDate ? new Date(input.yieldMaturityDate) : null,
          startDate: input.date ? new Date(input.date) : new Date(),
          payoutDay: Number(input.yieldPayoutDay || 15),
          principal: Number(input.quantity) * Number(input.avgPrice),
          targetAccountId: targetAccId,
        }
      })
    }

    const tradeInput = {
      accountId: typeof input.accountId === 'string' ? parseInt(input.accountId) : input.accountId,
      assetId: asset.id,
      type: 'BUY' as const,
      quantity: Number(input.quantity),
      price: Number(input.avgPrice),
      total: Number(input.quantity) * Number(input.avgPrice),
      fee: 0,
      date: input.date ? new Date(input.date) : new Date(),
      note: input.note,
    }

    const trade = await createTrade(tradeInput)
    return createSuccessResponse(trade, 'Position added')
  } catch (error) {
    console.error('createPositionAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create position',
      'POSITION_CREATE_ERROR'
    )
  }
}

export async function getYieldCalendarAction(year?: number, month?: number) {
  try {
    const y = year || new Date().getFullYear();
    const m = month || (new Date().getMonth() + 1);
    const calendar = await getYieldCalendar(y, m);
    return createSuccessResponse(calendar);
  } catch (error) {
    console.error("getYieldCalendarAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to fetch yield calendar",
      "YIELD_CALENDAR_ERROR"
    )
  }
}

export async function recordYieldPayoutAction(input: {
  assetId: number;
  amount: number;
  date: string;
  accountId: number;
}) {
  try {
    const res = await recordYieldPayout({
      assetId: input.assetId,
      amount: input.amount,
      date: new Date(input.date),
      accountId: input.accountId,
    });
    return createSuccessResponse(res, "Yield payout recorded successfully");
  } catch (error) {
    console.error("recordYieldPayoutAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to record yield payout",
      "YIELD_RECORD_ERROR"
    )
  }
}

export async function getYieldIncomesAction() {
  try {
    const incomes = await prisma.income.findMany({
      where: { NOT: { assetId: null } },
      include: { asset: true, account: true }
    });
    
    const serialized = incomes.map(inc => ({
      id: String(inc.id),
      date: inc.date.toISOString().split('T')[0],
      accountId: String(inc.accountId),
      accountName: inc.account?.name || 'Unknown',
      amount: Number(inc.amount),
      note: inc.note || '',
      assetId: inc.assetId,
      symbol: inc.asset?.symbol || '',
      currency: inc.account?.currency || 'IDR'
    }));
    
    return createSuccessResponse(serialized);
  } catch (error) {
    console.error("getYieldIncomesAction error:", error);
    return createErrorResponse(
      error instanceof Error ? error.message : "Failed to fetch yield incomes",
      "YIELD_INCOMES_ERROR"
    );
  }
}

export async function updatePositionAction(input: any) {
  try {
    if (!input.id || !input.quantity || !input.avgPrice) {
      return createErrorResponse('Missing required fields', 'MISSING_FIELDS')
    }

    const positionId = typeof input.id === 'string' ? parseInt(input.id) : input.id;
    const position = await prisma.investmentPosition.findUnique({
      where: { id: positionId },
      include: { asset: true },
    })
    if (!position) {
      return createErrorResponse('Position not found', 'POSITION_NOT_FOUND')
    }

    const oldQuantity = Number(position.quantity)
    const oldAvgPrice = Number(position.avgPrice)
    const oldTotal = oldQuantity * oldAvgPrice

    const newQuantity = Number(input.quantity)
    const newAvgPrice = Number(input.avgPrice)
    const newTotal = newQuantity * newAvgPrice
    const diff = newTotal - oldTotal

    // 1. Update Asset symbol, name, and class
    const assetClass = input.class || position.asset.class
    const asset = await prisma.investmentAsset.update({
      where: { id: position.assetId },
      data: {
        symbol: input.symbol ? input.symbol.toUpperCase() : position.asset.symbol,
        name: input.nama || position.asset.name,
        class: assetClass as any,
      }
    })

    // 2. Update yield config if provided
    if (input.yieldRate && input.yieldFrequency) {
      const targetAccId = input.yieldTargetAccountId
        ? (typeof input.yieldTargetAccountId === 'string' ? parseInt(input.yieldTargetAccountId) : input.yieldTargetAccountId)
        : position.accountId;

      await prisma.assetYieldConfig.upsert({
        where: { assetId: asset.id },
        update: {
          rate: Number(input.yieldRate),
          frequency: input.yieldFrequency,
          maturityDate: input.yieldMaturityDate ? new Date(input.yieldMaturityDate) : null,
          startDate: input.date ? new Date(input.date) : new Date(),
          payoutDay: Number(input.yieldPayoutDay || 15),
          principal: newTotal,
          targetAccountId: targetAccId,
        },
        create: {
          assetId: asset.id,
          rate: Number(input.yieldRate),
          frequency: input.yieldFrequency,
          maturityDate: input.yieldMaturityDate ? new Date(input.yieldMaturityDate) : null,
          startDate: input.date ? new Date(input.date) : new Date(),
          payoutDay: Number(input.yieldPayoutDay || 15),
          principal: newTotal,
          targetAccountId: targetAccId,
        }
      })
    } else {
      try {
        await prisma.assetYieldConfig.delete({ where: { assetId: asset.id } })
      } catch (e) {
        // ignore if not found
      }
    }

    // 3. Update the matching BUY trade for this position
    const trade = await prisma.investmentTrade.findFirst({
      where: {
        accountId: position.accountId,
        assetId: position.assetId,
        type: 'BUY',
      },
      orderBy: { date: 'asc' },
    })

    if (trade) {
      await prisma.investmentTrade.update({
        where: { id: trade.id },
        data: {
          quantity: newQuantity,
          price: newAvgPrice,
          total: newTotal,
          date: input.date ? new Date(input.date) : trade.date,
          note: input.note !== undefined ? input.note : trade.note,
        }
      })

      // 4. Update the LedgerEntry associated with the trade
      const ledgerEntry = await prisma.ledgerEntry.findFirst({
        where: {
          refType: 'INVESTMENT_BUY',
          refId: trade.id,
        }
      })

      if (ledgerEntry) {
        await prisma.ledgerEntry.update({
          where: { id: ledgerEntry.id },
          data: {
            amount: newTotal,
            date: input.date ? new Date(input.date) : ledgerEntry.date,
            note: input.note ? `Buy ${newQuantity} ${asset.symbol}` : ledgerEntry.note,
          }
        })
      }
    }

    // 5. Update the Position itself
    const updatedPos = await prisma.investmentPosition.update({
      where: { id: position.id },
      data: {
        quantity: newQuantity,
        avgPrice: newAvgPrice,
      }
    })

    // 6. Adjust parent account balance by diff (DEBIT means subtract from balance)
    const account = await prisma.account.findUnique({
      where: { id: position.accountId }
    })
    if (account) {
      const currentBalance = Number(account.balance)
      const newBalance = currentBalance - diff
      await prisma.account.update({
        where: { id: account.id },
        data: { balance: newBalance }
      })
    }

    return createSuccessResponse(updatedPos, 'Position updated successfully')
  } catch (error) {
    console.error('updatePositionAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update position',
      'POSITION_UPDATE_ERROR'
    )
  }
}

export async function deletePositionAction(positionId: number) {
  try {
    const position = await prisma.investmentPosition.findUnique({
      where: { id: positionId },
      include: { asset: true }
    })
    if (!position) {
      return createErrorResponse('Position not found', 'POSITION_NOT_FOUND')
    }

    // 1. Find all trades for this account and asset
    const trades = await prisma.investmentTrade.findMany({
      where: {
        accountId: position.accountId,
        assetId: position.assetId
      }
    })

    // 2. Revert account balances based on trade ledger entries and delete them
    const account = await prisma.account.findUnique({
      where: { id: position.accountId }
    })

    let balanceAdjustment = 0
    if (account) {
      for (const trade of trades) {
        // Find matching ledger entries
        const ledgerEntries = await prisma.ledgerEntry.findMany({
          where: {
            refId: trade.id,
            refType: { in: ['INVESTMENT_BUY', 'INVESTMENT_SELL'] }
          }
        })

        for (const entry of ledgerEntries) {
          const amount = Number(entry.amount)
          if (entry.direction === 'DEBIT') {
            // Revert DEBIT: add amount back to account balance
            balanceAdjustment += amount
          } else {
            // Revert CREDIT: subtract amount from account balance
            balanceAdjustment -= amount
          }
          
          // Delete LedgerEntry
          await prisma.ledgerEntry.delete({ where: { id: entry.id } })
        }

        // Delete the trade
        await prisma.investmentTrade.delete({ where: { id: trade.id } })
      }

      // Update the account balance
      const newBalance = Number(account.balance) + balanceAdjustment
      await prisma.account.update({
        where: { id: account.id },
        data: { balance: newBalance }
      })
    }

    // 3. Delete yield config if any
    try {
      await prisma.assetYieldConfig.delete({
        where: { assetId: position.assetId }
      })
    } catch (e) {
      // ignore if not found
    }

    // 4. Delete the position itself
    await prisma.investmentPosition.delete({
      where: { id: position.id }
    })

    return createSuccessResponse(true, 'Position deleted successfully')
  } catch (error) {
    console.error('deletePositionAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to delete position',
      'POSITION_DELETE_ERROR'
    )
  }
}
