import { prisma } from "@/lib/prisma";
import { createIncome } from "@/features/income/services/createIncome";
import { toNumber } from "@/lib/db";

export interface ProjectedYield {
  assetId: number;
  symbol: string;
  name: string;
  class: string;
  rate: number;
  amount: number;
  currency: string;
  payoutDate: string;
  status: "RECEIVED" | "PENDING";
  targetAccountId: number | null;
  targetAccountName: string;
  incomeId: number | null;
}

/**
 * Get projected and actual payouts for a specific month/year
 */
export async function getYieldCalendar(year: number, month: number): Promise<ProjectedYield[]> {
  // Get all yield configurations
  const configs = await prisma.assetYieldConfig.findMany({
    include: {
      asset: {
        include: {
          positions: {
            include: {
              account: true,
            },
          },
        },
      },
    },
  });

  const projections: ProjectedYield[] = [];
  const startOfMonth = new Date(year, month - 1, 1);
  const endOfMonth = new Date(year, month, 0, 23, 59, 59, 999);

  for (const config of configs) {
    const asset = config.asset;
    
    // Sum active positions (quantity > 0)
    const activePositions = asset.positions.filter(p => toNumber(p.quantity) > 0);
    if (activePositions.length === 0) continue;

    const totalQty = activePositions.reduce((s, p) => s + toNumber(p.quantity), 0);
    const avgPrice = activePositions.reduce((s, p) => s + toNumber(p.avgPrice) * toNumber(p.quantity), 0) / totalQty;
    const cost = totalQty * avgPrice;

    // Check if within date boundaries
    const startDate = new Date(config.startDate);
    const maturityDate = config.maturityDate ? new Date(config.maturityDate) : null;

    // Projected date in target month
    const projectedDate = new Date(year, month - 1, config.payoutDay);
    
    if (projectedDate < startDate) continue;
    if (maturityDate && projectedDate > maturityDate) continue;

    // Check if payout is due this month based on frequency
    const startYear = startDate.getFullYear();
    const startMonth = startDate.getMonth();
    const diffMonths = (year - startYear) * 12 + (month - 1 - startMonth);

    let isDue = false;
    const freq = config.frequency.toUpperCase();

    if (freq === "MONTHLY") {
      isDue = true;
    } else if (freq === "QUARTERLY") {
      isDue = diffMonths % 3 === 0;
    } else if (freq === "SEMI_ANNUALLY") {
      isDue = diffMonths % 6 === 0;
    } else if (freq === "ANNUALLY") {
      isDue = diffMonths % 12 === 0;
    } else if (freq === "ON_MATURITY" && maturityDate) {
      isDue = year === maturityDate.getFullYear() && (month - 1) === maturityDate.getMonth();
    }

    if (!isDue) continue;

    // Determine target account
    let targetAccountId = config.targetAccountId;
    let targetAccountName = "Belum Terasosiasi";
    if (targetAccountId) {
      const acc = await prisma.account.findUnique({ where: { id: targetAccountId } });
      if (acc) {
        targetAccountName = acc.name;
      }
    } else if (activePositions.length > 0) {
      // Fallback to the first account holding this asset
      targetAccountId = activePositions[0].accountId;
      targetAccountName = activePositions[0].account.name;
    } else {
      // Dynamic fallback: find first active bank or cash account
      const fallbackAcc = await prisma.account.findFirst({
        where: { type: { in: ["BANK", "CASH"] }, isActive: true },
        orderBy: { id: "asc" }
      });
      if (fallbackAcc) {
        targetAccountId = fallbackAcc.id;
        targetAccountName = fallbackAcc.name;
      }
    }

    // Payout amount calculations
    const rateNum = toNumber(config.rate);
    let principalNum = config.principal ? toNumber(config.principal) : cost;
    if (config.inKind) {
      principalNum = totalQty;
    }
    let amount = 0;

    if (freq === "MONTHLY") {
      amount = (principalNum * (rateNum / 100)) / 12;
    } else if (freq === "QUARTERLY") {
      amount = (principalNum * (rateNum / 100)) / 4;
    } else if (freq === "SEMI_ANNUALLY") {
      amount = (principalNum * (rateNum / 100)) / 2;
    } else {
      amount = principalNum * (rateNum / 100);
    }

    // Round to 2 decimals or 0 decimals for IDR
    const currency = config.inKind ? asset.symbol : (asset.baseCurrency || "IDR");
    if (config.inKind) {
      amount = Number(amount.toFixed(6));
    } else {
      amount = currency === "IDR" ? Math.round(amount) : Number(amount.toFixed(2));
    }

    // Check if payout has already been recorded as Income
    const existingIncome = await prisma.income.findFirst({
      where: {
        assetId: asset.id,
        date: {
          gte: startOfMonth,
          lte: endOfMonth,
        },
      },
    });

    projections.push({
      assetId: asset.id,
      symbol: asset.symbol,
      name: asset.name,
      class: asset.class,
      rate: rateNum,
      amount: existingIncome ? toNumber(existingIncome.amount) : amount,
      currency,
      payoutDate: projectedDate.toISOString().split("T")[0],
      status: existingIncome ? "RECEIVED" : "PENDING",
      targetAccountId,
      targetAccountName,
      incomeId: existingIncome ? existingIncome.id : null,
    });
  }

  return projections.sort((a, b) => new Date(a.payoutDate).getTime() - new Date(b.payoutDate).getTime());
}

/**
 * Record yield payout as an Income transaction
 */
export async function recordYieldPayout(input: {
  assetId: number;
  amount: number;
  date: Date;
  accountId: number;
}): Promise<any> {
  const asset = await prisma.investmentAsset.findUnique({
    where: { id: input.assetId },
    include: { yieldConfig: true }
  });
  if (!asset) throw new Error("Asset not found");

  // Determine Enum Values for yield payouts
  const typeRow = await prisma.enumValue.findFirst({
    where: { category: "income_type", value: "Investasi" },
  });
  if (!typeRow) throw new Error("Income type 'Investasi' not found");

  let sourceVal = "Dividen";
  if (asset.class === "BOND") {
    sourceVal = "Kupon";
  } else if (asset.class === "DEPOSIT") {
    sourceVal = "Bunga Deposito";
  }

  const sourceRow = await prisma.enumValue.findFirst({
    where: { category: "income_source", value: sourceVal },
  });
  if (!sourceRow) throw new Error(`Income source '${sourceVal}' not found`);

  const note = `${sourceVal} dari ${asset.name} (${asset.symbol})`;

  // If inKind yield is configured, adjust position directly and log 0-fiat Income
  if (asset.yieldConfig?.inKind) {
    const position = await prisma.investmentPosition.findUnique({
      where: {
        accountId_assetId: {
          accountId: input.accountId,
          assetId: input.assetId,
        }
      }
    });

    if (position) {
      const oldQty = toNumber(position.quantity);
      const oldAvgPrice = toNumber(position.avgPrice);
      const newQty = oldQty + input.amount;
      const newAvgPrice = newQty > 0 ? (oldQty * oldAvgPrice) / newQty : 0;

      await prisma.investmentPosition.update({
        where: {
          accountId_assetId: {
            accountId: input.accountId,
            assetId: input.assetId,
          }
        },
        data: {
          quantity: newQty,
          avgPrice: newAvgPrice,
        }
      });
    } else {
      await prisma.investmentPosition.create({
        data: {
          accountId: input.accountId,
          assetId: input.assetId,
          quantity: input.amount,
          avgPrice: 0,
        }
      });
    }

    return prisma.income.create({
      data: {
        date: input.date,
        typeId: typeRow.id,
        sourceId: sourceRow.id,
        accountId: input.accountId,
        amount: 0,
        note: `Staking Yield: +${input.amount} ${asset.symbol} (In-Kind)`,
        assetId: input.assetId,
      }
    });
  }

  // Call createIncome service, which creates Income, LedgerEntry, and adjusts Account balance
  return createIncome({
    date: input.date,
    typeId: typeRow.id,
    sourceId: sourceRow.id,
    accountId: input.accountId,
    amount: input.amount,
    note,
    assetId: input.assetId,
  });
}
