/**
 * Account Validation Schema
 * Yup validation untuk account management input
 */

import * as yup from 'yup'

export const createAccountSchema = yup.object().shape({
  name: yup
    .string()
    .required('Nama akun harus diisi')
    .min(3, 'Nama akun minimal 3 karakter')
    .max(100, 'Nama akun maksimal 100 karakter'),
  type: yup
    .string()
    .required('Tipe akun harus dipilih')
    .oneOf(['CASH', 'BANK', 'E_WALLET', 'INVESTMENT', 'LIABILITY'], 'Tipe akun tidak valid'),
  bucket: yup
    .string()
    .required('Bucket harus dipilih')
    .oneOf(['CASHFLOW', 'SAVING', 'INVESTMENT', 'LIABILITY'], 'Bucket tidak valid'),
  currency: yup
    .string()
    .required('Mata uang harus dipilih')
    .length(3, 'Kode mata uang harus 3 karakter'),
  initialBalance: yup
    .number()
    .min(0, 'Saldo awal tidak boleh negatif')
    .optional(),
  supportedClasses: yup
    .string()
    .optional(),
})

export const updateAccountSchema = yup.object().shape({
  id: yup.number().required().positive(),
  name: yup
    .string()
    .min(3, 'Nama akun minimal 3 karakter')
    .max(100, 'Nama akun maksimal 100 karakter')
    .optional(),
  currency: yup
    .string()
    .length(3, 'Kode mata uang harus 3 karakter')
    .optional(),
  isActive: yup.boolean().optional(),
  supportedClasses: yup
    .string()
    .optional(),
})

export type CreateAccountSchemaType = yup.InferType<typeof createAccountSchema>
export type UpdateAccountSchemaType = yup.InferType<typeof updateAccountSchema>
