/**
 * Investment Services
 * Business logic untuk investment trading dan portfolio management
 */

import { prisma } from '@/lib/prisma'
import { InvestmentTrade, InvestmentPosition } from '@prisma/client'
import { CreateTradeInput, PositionWithAsset, PortfolioSnapshot } from '../types/investment.type'
import { createTradeSchema } from '@/features/investment/schemas/trade.schema'
import { toDecimal, toNumber } from '@/lib/db'
import { createLedgerEntryTx } from '@/features/ledger/services/createLedgerEntry'

/**
 * Create investment trade (BUY/SELL) dengan position tracking
 */
export async function createTrade(
  input: CreateTradeInput
): Promise<InvestmentTrade> {
  // Validate
  await createTradeSchema.validate(input, { abortEarly: false })

  // Get asset
  const asset = await prisma.investmentAsset.findUnique({
    where: { id: input.assetId },
  })
  if (!asset) throw new Error(`Asset ${input.assetId} not found`)

  // Validate total
  if (input.total <= 0) throw new Error('Total must be greater than 0')

  // Create trade record
  const trade = await prisma.investmentTrade.create({
    data: {
      date: input.date || new Date(),
      accountId: input.accountId,
      assetId: input.assetId,
      type: input.type,
      quantity: toDecimal(input.quantity),
      price: toDecimal(input.price),
      fee: toDecimal(input.fee || 0),
      total: toDecimal(input.total),
      note: input.note,
    },
  })

  // Get account currency
  const account = await prisma.account.findUnique({
    where: { id: input.accountId },
  })
  if (!account) throw new Error(`Account ${input.accountId} not found`)

  // Update or create position
  let position = await prisma.investmentPosition.findUnique({
    where: {
      accountId_assetId: {
        accountId: input.accountId,
        assetId: asset.id,
      },
    },
  })

  if (input.type === 'BUY') {
    if (!position) {
      position = await prisma.investmentPosition.create({
        data: {
          accountId: input.accountId,
          assetId: input.assetId,
          quantity: toDecimal(input.quantity),
          avgPrice: toDecimal(input.price),
        },
      })
    } else {
      // Recalculate average price
      const oldQuantity = toNumber(position.quantity)
      const oldTotalCost = toNumber(position.avgPrice) * oldQuantity
      const newQuantity = oldQuantity + input.quantity
      const newTotalCost = oldTotalCost + input.total
      const newAvgPrice = newTotalCost / newQuantity

      position = await prisma.investmentPosition.update({
        where: {
          accountId_assetId: {
            accountId: input.accountId,
            assetId: input.assetId,
          },
        },
        data: {
          quantity: toDecimal(newQuantity),
          avgPrice: toDecimal(newAvgPrice),
        },
      })
    }

    // DEBIT from account
    await createLedgerEntryTx({
      accountId: input.accountId,
      direction: 'DEBIT',
      amount: input.total,
      currency: input.feeCurrency || account.currency,
      refType: 'INVESTMENT_BUY',
      refId: trade.id,
      note: `Buy ${input.quantity} ${asset.symbol}`,
    })
  } else {
    // SELL
    if (!position) throw new Error(`No position for asset ${input.assetId}`)

    const remainingQuantity = toNumber(position.quantity) - input.quantity
    if (remainingQuantity < 0) {
      throw new Error('Insufficient quantity to sell')
    }

    if (remainingQuantity === 0) {
      await prisma.investmentPosition.delete({
        where: {
          accountId_assetId: {
            accountId: input.accountId,
            assetId: input.assetId,
          },
        },
      })
    } else {
      await prisma.investmentPosition.update({
        where: {
          accountId_assetId: {
            accountId: input.accountId,
            assetId: input.assetId,
          },
        },
        data: {
          quantity: toDecimal(remainingQuantity),
        },
      })
    }

    // CREDIT to account (proceeds after fee)
    const proceeds = input.quantity * input.price - (input.fee || 0)
    await createLedgerEntryTx({
      accountId: input.accountId,
      direction: 'CREDIT',
      amount: proceeds,
      currency: input.feeCurrency || account.currency,
      refType: 'INVESTMENT_SELL',
      refId: trade.id,
      note: `Sell ${input.quantity} ${asset.symbol}`,
    })
  }

  return trade
}

/**
 * Get all positions dengan asset info
 */
export async function getPositions(
  accountId: number
): Promise<PositionWithAsset[]> {
  const positions = await prisma.investmentPosition.findMany({
    where: { accountId },
    include: { asset: true },
  })

  return positions as unknown as PositionWithAsset[]
}

/**
 * Get portfolio snapshot (summary)
 */
export async function getPortfolioSnapshot(
  accountId: number
): Promise<PortfolioSnapshot> {
  const positions = await getPositions(accountId)

  let totalInvested = 0
  const holdings: Record<string, { quantity: number; cost: number }> = {}

  for (const pos of positions) {
    const quantity = toNumber(pos.quantity)
    const avgPrice = toNumber(pos.avgPrice)
    const totalCost = quantity * avgPrice
    totalInvested += totalCost
    
    if (pos.asset) {
      holdings[pos.asset.symbol] = {
        quantity,
        cost: totalCost,
      }
    }
  }

  return {
    totalInvested,
    currentValue: totalInvested,
    totalPnL: 0,
    pnLPercent: 0,
    positions,
  }
}

/**
 * Get all trades optionally filtered by account
 */
 export async function getTrades(
   accountId?: number
 ): Promise<InvestmentTrade[]> {
   const where: any = {}
   if (accountId) where.accountId = accountId
   return prisma.investmentTrade.findMany({ where })
 }

/**
 * Find existing asset by symbol or create new one
 */
 export async function findOrCreateAsset(
   symbol: string,
   name?: string,
   assetClass: string = "STOCK",
   baseCurrency: string = "USD"
 ) {
   let asset = await prisma.investmentAsset.findFirst({ where: { symbol } })
   if (!asset) {
     asset = await prisma.investmentAsset.create({
       data: {
         symbol,
         name: name || symbol,
         class: assetClass as any,
         baseCurrency,
         isActive: true,
       },
     })
   }
   return asset
 }
