/**
 * Response Helper Types
 * Utilities untuk membuat response yang consistent
 */

import { ApiResponse, PaginatedData } from './api.type'

function sanitize<T>(data: T): T {
  if (data === undefined || data === null) return data
  return JSON.parse(JSON.stringify(data))
}

export function createSuccessResponse<T>(
  data: T,
  message?: string
): Extract<ApiResponse<T>, { success: true }> {
  return {
    success: true,
    data: sanitize(data),
    message,
  }
}

export function createErrorResponse(
  error: string,
  code?: string,
  details?: Record<string, any>
): Extract<ApiResponse, { success: false }> {
  return {
    success: false,
    error,
    code,
    details,
  }
}

export function createPaginatedResponse<T>(
  items: T[],
  total: number,
  page: number,
  pageSize: number,
  message?: string
): Extract<ApiResponse<PaginatedData<T>>, { success: true }> {
  const totalPages = Math.ceil(total / pageSize)
  
  return {
    success: true,
    data: {
      items: sanitize(items),
      total,
      page,
      pageSize,
      totalPages,
      hasNextPage: page < totalPages,
      hasPrevPage: page > 1,
    },
    message,
  }
}
