/**
 * Transfer Services
 * Business logic untuk balance transfer dengan fee calculation
 */

import { prisma } from '@/lib/prisma'
import { BalanceTransfer } from '@prisma/client'
import { CreateTransferInput, UpdateTransferInput, TransferFeeBreakdown } from '../types/transfer.type'
import { createTransferSchema, updateTransferSchema } from '@/features/transfer/schemas/transfer.schema'
import { toDecimal, toNumber } from '@/lib/db'
import { createLedgerEntryTx } from '@/features/ledger/services/createLedgerEntry'

/**
 * Calculate transfer fee breakdown
 */
export function calculateTransferFee(
  amount: number,
  feeFixed: number = 0,
  feePercent: number = 0
): TransferFeeBreakdown {
  const fixedFee = feeFixed
  const percentFee = amount * (feePercent / 100)
  const totalFee = fixedFee + percentFee
  const netAmount = amount - totalFee

  return {
    transferAmount: amount,
    fixedFee,
    percentFee,
    totalFee,
    netAmount,
  }
}

/**
 * Create balance transfer dengan ledger entries (DEBIT from/CREDIT to)
 */
export async function createTransfer(
  input: CreateTransferInput
): Promise<BalanceTransfer> {
  // Validate
  await createTransferSchema.validate(input, { abortEarly: false })

  // Get from account
  const fromAccount = await prisma.account.findUnique({
    where: { id: input.fromAccountId },
  })
  if (!fromAccount) throw new Error(`Account ${input.fromAccountId} not found`)

  // Calculate fee
  const feeBreakdown = calculateTransferFee(
    input.amount,
    input.feeFixed || 0,
    input.feePercent || 0
  )

  // Verify from account has sufficient balance
  if (toNumber(fromAccount.balance) < input.amount + feeBreakdown.totalFee) {
    throw new Error('Insufficient balance for transfer')
  }

  // Create transfer record
  const transfer = await prisma.balanceTransfer.create({
    data: {
      date: input.date || new Date(),
      fromAccountId: input.fromAccountId,
      toAccountId: input.toAccountId,
      amount: toDecimal(input.amount),
      feeFixed: toDecimal(feeBreakdown.fixedFee),
      feePercent: toDecimal(input.feePercent || 0),
      note: input.note,
    },
  })

  // Create ledger entries
  // DEBIT from account (amount + fee)
  await createLedgerEntryTx({
    accountId: input.fromAccountId,
    direction: 'DEBIT',
    amount: input.amount + feeBreakdown.totalFee,
    currency: fromAccount.currency,
    refType: 'TRANSFER',
    refId: transfer.id,
    note: `Transfer out to account ${input.toAccountId}`,
  })

  // CREDIT to account (amount only, no fee)
  const toAccount = await prisma.account.findUnique({
    where: { id: input.toAccountId },
  })
  await createLedgerEntryTx({
    accountId: input.toAccountId,
    direction: 'CREDIT',
    amount: input.amount,
    currency: toAccount?.currency || fromAccount.currency,
    refType: 'TRANSFER',
    refId: transfer.id,
    note: `Transfer in from account ${input.fromAccountId}`,
  })

  return transfer
}

/**
 * Get transfer list dengan pagination
 */
export async function getTransferList(query?: {
  page?: number
  pageSize?: number
  startDate?: Date
  endDate?: Date
  fromAccountId?: number
  toAccountId?: number
}): Promise<{ transfers: BalanceTransfer[]; total: number }> {
  const page = query?.page || 1
  const pageSize = query?.pageSize || 10
  const skip = (page - 1) * pageSize

  const transfers = await prisma.balanceTransfer.findMany({
    where: {
      date:
        query?.startDate || query?.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      fromAccountId: query?.fromAccountId,
      toAccountId: query?.toAccountId,
    },
    orderBy: { date: 'desc' },
    skip,
    take: pageSize,
  })

  const total = await prisma.balanceTransfer.count({
    where: {
      date:
        query?.startDate || query?.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      fromAccountId: query?.fromAccountId,
      toAccountId: query?.toAccountId,
    },
  })

  return { transfers, total }
}

/**
 * Get transfer by ID
 */
export async function getTransferById(
  transferId: number
): Promise<BalanceTransfer | null> {
  return prisma.balanceTransfer.findUnique({
    where: { id: transferId },
  })
}

/**
 * Delete transfer dan reverse ledger entries
 */
export async function deleteTransfer(transferId: number): Promise<void> {
  const transfer = await getTransferById(transferId)
  if (!transfer) throw new Error(`Transfer ${transferId} not found`)

  // Delete ledger entries
  await prisma.ledgerEntry.deleteMany({
    where: {
      refType: 'TRANSFER',
      refId: transfer.id,
    },
  })

  // Rebuild account balances
  for (const accountId of [transfer.fromAccountId, transfer.toAccountId]) {
    const entries = await prisma.ledgerEntry.findMany({
      where: { accountId },
    })
    let balance = 0
    for (const entry of entries) {
      const amount = toNumber(entry.amount)
      balance = entry.direction === 'CREDIT' ? balance + amount : balance - amount
    }
    await prisma.account.update({
      where: { id: accountId },
      data: { balance: toDecimal(balance) },
    })
  }

  // Delete transfer
  await prisma.balanceTransfer.delete({
    where: { id: transferId },
  })
}

export async function updateTransfer(input: UpdateTransferInput): Promise<BalanceTransfer> {
  await updateTransferSchema.validate(input, { abortEarly: false })

  const existing = await getTransferById(input.id)
  if (!existing) throw new Error(`Transfer ${input.id} not found`)

  // we will delete old ledger entries and rebuild after updating
  const updated = await prisma.balanceTransfer.update({
    where: { id: input.id },
    data: {
      date: input.date || existing.date,
      fromAccountId: input.fromAccountId,
      toAccountId: input.toAccountId,
      amount: toDecimal(input.amount),
      feeFixed: toDecimal(input.feeFixed || 0),
      feePercent: toDecimal(input.feePercent || 0),
      note: input.note,
    },
  })

  // rebuild ledger entries same as create but for updated transfer
  await prisma.ledgerEntry.deleteMany({ where: { refType: 'TRANSFER', refId: updated.id } })

  // DEBIT from
  const fromAcc = await prisma.account.findUnique({ where: { id: updated.fromAccountId } })
  if (!fromAcc) throw new Error(`Account ${updated.fromAccountId} not found`)
  await createLedgerEntryTx({
    accountId: updated.fromAccountId,
    direction: 'DEBIT',
    amount: toNumber(updated.amount) + toNumber(updated.feeFixed || 0) + (toNumber(updated.amount) * toNumber(updated.feePercent || 0) / 100),
    currency: fromAcc.currency,
    refType: 'TRANSFER',
    refId: updated.id,
    note: `Transfer out to account ${updated.toAccountId}`,
  })

  // CREDIT to
  const toAcc = await prisma.account.findUnique({ where: { id: updated.toAccountId } })
  await createLedgerEntryTx({
    accountId: updated.toAccountId,
    direction: 'CREDIT',
    amount: toNumber(updated.amount),
    currency: toAcc?.currency || fromAcc.currency,
    refType: 'TRANSFER',
    refId: updated.id,
    note: `Transfer in from account ${updated.fromAccountId}`,
  })

  // rebuild balances for affected accounts
  for (const accountId of [existing.fromAccountId, existing.toAccountId, updated.fromAccountId, updated.toAccountId]) {
    const entries = await prisma.ledgerEntry.findMany({ where: { accountId } })
    let balance = 0
    for (const entry of entries) {
      const amount = toNumber(entry.amount)
      balance = entry.direction === 'CREDIT' ? balance + amount : balance - amount
    }
    await prisma.account.update({ where: { id: accountId }, data: { balance: toDecimal(balance) } })
  }

  return updated
}
