/**
 * Transfer Validation Schema
 * Yup validation untuk balance transfer input
 */

import * as yup from 'yup'

export const createTransferSchema = yup.object().shape({
  date: yup.date().required('Tanggal harus diisi').typeError('Format tanggal tidak valid'),
  fromAccountId: yup
    .number()
    .required('Akun asal harus dipilih')
    .positive('Akun asal tidak valid'),
  toAccountId: yup
    .number()
    .required('Akun tujuan harus dipilih')
    .positive('Akun tujuan tidak valid'),
  amount: yup
    .number()
    .required('Nominal harus diisi')
    .positive('Nominal harus lebih dari 0')
    .typeError('Nominal harus berupa angka'),
  feeFixed: yup
    .number()
    .min(0, 'Biaya fixed tidak boleh negatif')
    .optional(),
  feePercent: yup
    .number()
    .min(0, 'Biaya persen tidak boleh negatif')
    .max(100, 'Biaya persen maksimal 100%')
    .optional(),
  note: yup.string().max(500, 'Catatan maksimal 500 karakter').optional(),
})

export const updateTransferSchema = createTransferSchema.shape({
  id: yup.number().required().positive(),
})

export type CreateTransferSchemaType = yup.InferType<typeof createTransferSchema>
export type UpdateTransferSchemaType = yup.InferType<typeof updateTransferSchema>
