/**
 * Ledger Services
 * Business logic untuk ledger entries (source of truth)
 */

import { prisma } from '@/lib/prisma'
import { LedgerEntry } from '@prisma/client'
import { CreateLedgerEntryInput, LedgerListQuery, LedgerBalance } from '../types/ledger.type'
import { toDecimal, toNumber } from '@/lib/db'
import { updateAccountBalance } from '@/features/account/services/getAccounts'

/**
 * Create ledger entry dan update account balance
 */
export async function createLedgerEntryTx(
  input: CreateLedgerEntryInput
): Promise<LedgerEntry> {
  const entry = await prisma.ledgerEntry.create({
    data: {
      date: input.date ? new Date(input.date) : new Date(),
      accountId: input.accountId,
      direction: input.direction,
      amount: toDecimal(input.amount),
      currency: input.currency,
      refType: input.refType,
      refId: input.refId,
      note: input.note,
    },
  })

  // Update account balance
  await updateAccountBalance(input.accountId, input.amount, input.direction)

  return entry
}

/**
 * Get ledger entries dengan pagination dan filter
 */
export async function getLedgerEntries(
  query: LedgerListQuery
): Promise<{ entries: LedgerEntry[]; total: number }> {
  const page = query.page || 1
  const pageSize = query.pageSize || 10
  const skip = (page - 1) * pageSize

  const entries = await prisma.ledgerEntry.findMany({
    where: {
      accountId: query.accountId,
      direction: query.direction,
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
    },
    orderBy: { date: 'desc' },
    skip,
    take: pageSize,
  })

  const total = await prisma.ledgerEntry.count({
    where: {
      accountId: query.accountId,
      direction: query.direction,
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
    },
  })

  return { entries, total }
}

/**
 * Get account ledger balance (DEBIT vs CREDIT)
 */
export async function getAccountLedgerBalance(
  accountId: number,
  startDate?: Date,
  endDate?: Date
): Promise<LedgerBalance> {
  const entries = await prisma.ledgerEntry.findMany({
    where: {
      accountId,
      date:
        startDate || endDate
          ? {
              gte: startDate,
              lte: endDate,
            }
          : undefined,
    },
  })

  let totalDebit = 0
  let totalCredit = 0
  const currency = entries[0]?.currency || 'IDR'

  for (const entry of entries) {
    const amount = toNumber(entry.amount)
    if (entry.direction === 'DEBIT') {
      totalDebit += amount
    } else {
      totalCredit += amount
    }
  }

  return {
    accountId,
    currency,
    totalDebit,
    totalCredit,
    balance: totalCredit - totalDebit,
  }
}

/**
 * Rebuild account balance dari ledger (recovery)
 */
export async function rebuildAccountBalance(accountId: number): Promise<number> {
  const ledgerBalance = await getAccountLedgerBalance(accountId)

  await prisma.account.update({
    where: { id: accountId },
    data: { balance: toDecimal(ledgerBalance.balance) },
  })

  return ledgerBalance.balance
}
