/**
 * Database Utilities
 * Helper functions untuk database operations yang common
 */

import { prisma } from './prisma'

/**
 * Safely convert number to Decimal (returns Decimal type)
 */
export function toDecimal(value: any): any {
  if (typeof value === 'object' && value !== null && value.constructor?.name === 'Decimal') {
    return value
  }
  return value
}

/**
 * Safely convert Decimal to number
 */
export function toNumber(value: any): number {
  if (typeof value === 'number') return value
  if (typeof value === 'string') return parseFloat(value)
  if (typeof value === 'object' && value !== null && value.toNumber) return value.toNumber()
  return Number(value)
}

/**
 * Format decimal untuk display (tidak round, truncate)
 */
export function formatDecimal(value: any, places: number = 2): string {
  const num = toNumber(value)
  const factor = Math.pow(10, places)
  return (Math.floor(num * factor) / factor).toString()
}

/**
 * Validate if value is valid decimal amount
 */
export function isValidAmount(value: any): boolean {
  if (typeof value === 'number' && value > 0 && isFinite(value)) return true
  if (typeof value === 'string') {
    const num = parseFloat(value)
    return num > 0 && isFinite(num)
  }
  if (typeof value === 'object' && value !== null && value.greaterThan) return value.greaterThan(0)
  return false
}

/**
 * Create ledger entry untuk transaction
 */
export async function createLedgerEntry(data: {
  accountId: number
  direction: 'DEBIT' | 'CREDIT'
  amount: number | string | any
  currency: string
  refType?: string
  refId?: number
  note?: string
}) {
  return prisma.ledgerEntry.create({
    data: {
      date: new Date(),
      accountId: data.accountId,
      direction: data.direction,
      amount: toDecimal(data.amount),
      currency: data.currency,
      refType: data.refType,
      refId: data.refId,
      note: data.note,
    },
  })
}

/**
 * Get account with all relations
 */
export async function getAccountWithDetails(accountId: number) {
  return prisma.account.findUnique({
    where: { id: accountId },
    include: {
      incomes: true,
      outcomes: true,
      transfersFrom: true,
      transfersTo: true,
      trades: true,
      positions: true,
    },
  })
}

/**
 * Get ledger for account between dates
 */
export async function getLedgerRange(
  accountId: number,
  startDate: Date,
  endDate: Date
) {
  return prisma.ledgerEntry.findMany({
    where: {
      accountId,
      date: {
        gte: startDate,
        lte: endDate,
      },
    },
    orderBy: { date: 'desc' },
  })
}
