/**
 * Ledger Validation Schema
 * Yup validation untuk ledger entry input (tabungan & kewajiban)
 */

import * as yup from 'yup'

export const createLedgerSchema = yup.object().shape({
  accountId: yup
    .number()
    .required('Akun harus dipilih')
    .positive('Akun tidak valid'),
  direction: yup
    .string()
    .required('Arah mutasi harus ditentukan')
    .oneOf(['DEBIT', 'CREDIT'], 'Arah mutasi tidak valid'),
  amount: yup
    .number()
    .required('Nominal harus diisi')
    .positive('Nominal harus lebih dari 0')
    .typeError('Nominal harus berupa angka'),
  currency: yup
    .string()
    .required('Mata uang harus ditentukan')
    .length(3, 'Kode mata uang harus 3 karakter'),
  refType: yup.string().optional().nullable(),
  refId: yup.number().optional().nullable(),
  note: yup.string().max(500, 'Catatan maksimal 500 karakter').optional().nullable(),
  date: yup.date().optional().nullable().typeError('Format tanggal tidak valid'),
})

export const updateLedgerSchema = createLedgerSchema.shape({
  id: yup.number().required().positive(),
})

export type CreateLedgerSchemaType = yup.InferType<typeof createLedgerSchema>
export type UpdateLedgerSchemaType = yup.InferType<typeof updateLedgerSchema>
