import { prisma } from './prisma'

type ExchangeProvider = {
  url: string
  source: string
  parser: (data: any) => { rates: Record<string, number>; updatedAt: Date | null }
}

const providers: ExchangeProvider[] = [
  {
    url: 'https://open.er-api.com/v6/latest/USD',
    source: 'open.er-api.com/v6',
    parser: (data: any) => {
      if (data?.result !== 'success') return { rates: {}, updatedAt: null }
      return {
        rates: data.rates || {},
        updatedAt: data.time_last_update_unix ? new Date(data.time_last_update_unix * 1000) : null
      }
    }
  },
  {
    url: 'https://api.exchangerate-api.com/v4/latest/USD',
    source: 'exchangerate-api.com/v4',
    parser: (data: any) => {
      if (data?.base !== 'USD') return { rates: {}, updatedAt: null }
      return {
        rates: data.rates || {},
        updatedAt: data.time_last_updated ? new Date(data.time_last_updated * 1000) : null
      }
    }
  },
  {
    url: 'https://cdn.moneyconvert.net/api/latest.json',
    source: 'moneyconvert.net',
    parser: (data: any) => {
      if (data?.base !== 'USD') return { rates: {}, updatedAt: null }
      return {
        rates: data.rates || {},
        updatedAt: data.ts ? new Date(data.ts) : null
      }
    }
  },
  {
    url: 'https://api.frankfurter.dev/v1/latest?base=USD',
    source: 'frankfurter.dev',
    parser: (data: any) => {
      if (data?.base !== 'USD') return { rates: {}, updatedAt: null }
      const rates = data.rates || {}
      rates['USD'] = 1.0
      return {
        rates,
        updatedAt: data.date ? new Date(data.date) : null
      }
    }
  }
]

export async function fetchExchangeRates(): Promise<string | null> {
  for (const provider of providers) {
    try {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 10000)

      const response = await fetch(provider.url, { signal: controller.signal })
      clearTimeout(timeoutId)

      if (!response.ok) {
        console.warn(`ExchangeRate: ${provider.source} returned HTTP ${response.status}`)
        continue
      }

      const payload = await response.json()
      if (!payload) {
        console.warn(`ExchangeRate: ${provider.source} returned empty payload`)
        continue
      }

      const { rates, updatedAt } = provider.parser(payload)
      if (Object.keys(rates).length === 0) {
        console.warn(`ExchangeRate: ${provider.source} parser returned no rates`)
        continue
      }

      await persistRates(rates, provider.source, updatedAt)
      console.log(`ExchangeRate: fetched successfully from ${provider.source}`)
      
      return provider.source
    } catch (error: any) {
      console.warn(`ExchangeRate: ${provider.source} failed — ${error.message}`)
    }
  }

  console.error('ExchangeRate: all providers failed')
  return null
}

async function persistRates(rates: Record<string, number>, source: string, rateUpdatedAt: Date | null) {
  const currencies = await prisma.currency.findMany({
    where: { isActive: true }
  })

  const now = new Date()

  for (const currency of currencies) {
    const code = currency.code
    const rate = rates[code]

    if (rate === undefined || rate === null || rate <= 0) {
      continue
    }

    await prisma.exchangeRate.upsert({
      where: { currencyId: currency.id },
      update: {
        rate: rate,
        source: source,
        rateUpdatedAt: rateUpdatedAt,
        fetchedAt: now
      },
      create: {
        currencyId: currency.id,
        rate: rate,
        source: source,
        rateUpdatedAt: rateUpdatedAt,
        fetchedAt: now
      }
    })
  }
}

function isDataStale(lastFetchedAt: Date | null): boolean {
  if (!lastFetchedAt) return true

  const now = new Date()
  
  const currentHour = now.getHours()
  const currentIntervalStartHour = Math.floor(currentHour / 6) * 6
  
  const windowStartTimestamp = new Date(now)
  windowStartTimestamp.setHours(currentIntervalStartHour, 0, 0, 0)

  return lastFetchedAt.getTime() < windowStartTimestamp.getTime()
}

export async function autoRefreshIfNeeded() {
  try {
    const latestRate = await prisma.exchangeRate.findFirst({
      orderBy: { fetchedAt: 'desc' }
    })

    if (!latestRate || isDataStale(latestRate.fetchedAt)) {
      console.log('ExchangeRate: Data stale or missing. Triggering scheduled refresh.')
      await fetchExchangeRates()
    }
  } catch (err) {
    console.error('ExchangeRate: failed to perform check/auto-refresh:', err)
  }
}

export async function getLatestRates() {
  await autoRefreshIfNeeded()

  return prisma.currency.findMany({
    include: {
      exchangeRate: true
    }
  })
}

export async function convertAmount(amount: number, fromCode: string, toCode: string): Promise<number | null> {
  if (fromCode === toCode) {
    return amount
  }

  const codes = [fromCode, toCode]
  const currencies = await prisma.currency.findMany({
    where: { code: { in: codes } },
    include: { exchangeRate: true }
  })

  const fromCur = currencies.find(c => c.code === fromCode)
  const toCur = currencies.find(c => c.code === toCode)

  const fromRate = fromCode === 'USD' ? 1.0 : Number(fromCur?.exchangeRate?.rate)
  const toRate = toCode === 'USD' ? 1.0 : Number(toCur?.exchangeRate?.rate)

  if (!fromRate || !toRate) {
    return null
  }

  return (amount / fromRate) * toRate
}
