'use server'

import { getLatestRates, fetchExchangeRates, convertAmount } from '@/lib/exchange-rate'

export async function getLatestRatesAction() {
  try {
    const rates = await getLatestRates()
    const serialized = rates.map(c => ({
      code: c.code,
      symbol: c.symbol,
      rate: Number(c.exchangeRate?.rate) || (c.code === 'USD' ? 1 : null),
      updatedAt: c.exchangeRate?.rateUpdatedAt?.toISOString() || null,
      fetchedAt: c.exchangeRate?.fetchedAt?.toISOString() || null
    }))

    return { success: true, data: serialized }
  } catch (error: any) {
    return { success: false, message: error.message }
  }
}

export async function refreshExchangeRatesAction() {
  try {
    const source = await fetchExchangeRates()
    return { success: true, source }
  } catch (error: any) {
    return { success: false, message: error.message }
  }
}
