'use server'

import { prisma } from '@/lib/prisma'
import {
  createSuccessResponse,
  createErrorResponse,
} from '@/types/response.type'

export async function getEnumsAction(category: string, parentId?: number) {
  try {
    if (!category) {
      return createErrorResponse('Missing category', 'MISSING_CATEGORY')
    }

    const where: any = { category }
    if (parentId !== undefined) where.parentId = parentId

    const values = await prisma.enumValue.findMany({ where })
    return createSuccessResponse(values)
  } catch (error) {
    console.error('getEnumsAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch enum values',
      'ENUM_FETCH_ERROR'
    )
  }
}

export async function createEnumAction(input: any) {
  try {
    const { category, value, description, order, parentId } = input
    if (!category || !value) {
      return createErrorResponse('Category and value are required', 'MISSING_FIELDS')
    }

    const data: any = { category, value }
    if (description !== undefined) data.description = description
    if (order !== undefined) data.order = order
    if (parentId !== undefined) data.parentId = parentId

    const created = await prisma.enumValue.create({ data })
    return createSuccessResponse(created, 'Enum value created')
  } catch (error) {
    console.error('createEnumAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to create enum value',
      'ENUM_CREATE_ERROR'
    )
  }
}

export async function updateEnumAction(input: any) {
  try {
    const { id, value, description, order, parentId } = input
    if (!id) {
      return createErrorResponse('Missing id', 'MISSING_ID')
    }

    const data: any = {}
    if (value !== undefined) data.value = value
    if (description !== undefined) data.description = description
    if (order !== undefined) data.order = order
    if (parentId !== undefined) data.parentId = parentId

    const updated = await prisma.enumValue.update({ where: { id }, data })
    return createSuccessResponse(updated, 'Enum value updated')
  } catch (error) {
    console.error('updateEnumAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to update enum value',
      'ENUM_UPDATE_ERROR'
    )
  }
}

export async function deleteEnumAction(id: number) {
  try {
    if (!id) {
      return createErrorResponse('Missing id', 'MISSING_ID')
    }

    const deleted = await prisma.enumValue.delete({ where: { id } })
    return createSuccessResponse(deleted, 'Enum value deleted')
  } catch (error) {
    console.error('deleteEnumAction error:', error)
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to delete enum value',
      'ENUM_DELETE_ERROR'
    )
  }
}
