/**
 * Outcome Validation Schema
 * Yup validation untuk outcome transaction input
 */

import * as yup from 'yup'

export const createOutcomeSchema = yup.object().shape({
  date: yup.date().required('Tanggal harus diisi').typeError('Format tanggal tidak valid'),
  categoryId: yup
    .number()
    .required('Kategori harus dipilih')
    .positive('Kategori tidak valid'),
  subcategoryId: yup
    .number()
    .positive('Subkategori tidak valid')
    .optional(),
  accountId: yup
    .number()
    .required('Akun harus dipilih')
    .positive('Akun tidak valid'),
  amount: yup
    .number()
    .required('Nominal harus diisi')
    .positive('Nominal harus lebih dari 0')
    .typeError('Nominal harus berupa angka'),
  note: yup.string().max(500, 'Catatan maksimal 500 karakter').optional(),
})

export const updateOutcomeSchema = createOutcomeSchema.shape({
  id: yup.number().required().positive(),
})

export type CreateOutcomeSchemaType = yup.InferType<typeof createOutcomeSchema>
export type UpdateOutcomeSchemaType = yup.InferType<typeof updateOutcomeSchema>
