import { PrismaClient } from '@prisma/client';
import { PrismaBetterSqlite3 } from '@prisma/adapter-better-sqlite3';

const globalForPrisma = global as unknown as { prisma: PrismaClient };

const sqliteUrl = process.env.DATABASE_URL ? process.env.DATABASE_URL.replace(/^file:/, '') : ':memory:';
const sqliteAdapter = new PrismaBetterSqlite3({ url: sqliteUrl });

const prismaLogLevel: Array<'query' | 'info' | 'warn' | 'error'> = process.env.PRISMA_LOG
  ? (process.env.PRISMA_LOG.split(',') as any)
  : process.env.NODE_ENV === 'production'
  ? ['warn', 'error']
  : ['query', 'info', 'warn', 'error'];

export const prisma =
  globalForPrisma.prisma ||
  new PrismaClient({
    adapter: sqliteAdapter,
    log: prismaLogLevel,
  });

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;