/**
 * Income Services
 * Business logic untuk income management
 */

import { prisma } from '@/lib/prisma'
import { Income } from '@prisma/client'
import { CreateIncomeInput, UpdateIncomeInput, IncomeListQuery, IncomeSummary } from '../types/income.type'
import { createIncomeSchema, updateIncomeSchema } from '@/features/income/schemas/income.schema'
import { toDecimal, toNumber } from '@/lib/db'
import { createLedgerEntryTx } from '@/features/ledger/services/createLedgerEntry'
import { getAccountById } from '@/features/account/services/getAccounts'

/**
 * Create new income dengan automatic ledger entry
 */
export async function createIncome(input: CreateIncomeInput): Promise<Income> {
  // Validate input
  await createIncomeSchema.validate(input, { abortEarly: false })

  // Get account to determine currency
  const account = await getAccountById(input.accountId)
  if (!account) throw new Error(`Account ${input.accountId} not found`)

  // Create income record
  const income = await prisma.income.create({
    data: {
      date: input.date,
      typeId: input.typeId,
      sourceId: input.sourceId,
      accountId: input.accountId,
      amount: toDecimal(input.amount),
      note: input.note,
      assetId: input.assetId,
    },
  })

  // Create ledger entry (CREDIT)
  await createLedgerEntryTx({
    accountId: input.accountId,
    direction: 'CREDIT',
    amount: input.amount,
    currency: account.currency,
    refType: 'INCOME',
    refId: income.id,
    note: `Income: ${income.note || 'N/A'}`,
  })

  return income
}

/**
 * Get income list dengan pagination dan filter
 */
export async function getIncomeList(
  query: IncomeListQuery
): Promise<{ incomes: Income[]; total: number }> {
  const page = query.page || 1
  const pageSize = query.pageSize || 10
  const skip = (page - 1) * pageSize

  const incomes = await prisma.income.findMany({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
    },
    orderBy: { date: 'desc' },
    skip,
    take: pageSize,
  })

  const total = await prisma.income.count({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
    },
  })

  return { incomes, total }
}

/**
 * Get income by ID
 */
export async function getIncomeById(incomeId: number): Promise<Income | null> {
  return prisma.income.findUnique({
    where: { id: incomeId },
  })
}

/**
 * Get income summary
 */
export async function getIncomeSummary(
  query: IncomeListQuery
): Promise<IncomeSummary> {
  const incomes = await prisma.income.findMany({
    where: {
      date:
        query.startDate || query.endDate
          ? {
              gte: query.startDate,
              lte: query.endDate,
            }
          : undefined,
      accountId: query.accountId,
    },
  })

  let totalIncome = 0

  for (const income of incomes) {
    const amount = toNumber(income.amount)
    totalIncome += amount
  }

  const transactionCount = incomes.length
  const averageTransaction = transactionCount > 0 ? totalIncome / transactionCount : 0
  const account = query.accountId ? await getAccountById(query.accountId) : null

  return {
    totalIncome,
    transactionCount,
    averageTransaction,
    currency: account?.currency || 'IDR',
  }
}

/**
 * Delete income dan reverse ledger entry
 */
export async function deleteIncome(incomeId: number): Promise<void> {
  const income = await getIncomeById(incomeId)
  if (!income) throw new Error(`Income ${incomeId} not found`)

  // Delete ledger entry
  await prisma.ledgerEntry.deleteMany({
    where: {
      refType: 'INCOME',
      refId: income.id,
    },
  })

  // Rebuild account balance
  await prisma.account.update({
    where: { id: income.accountId },
    data: { balance: await rebuildAccountBalanceFromLedger(income.accountId) },
  })

  // Delete income
  await prisma.income.delete({
    where: { id: incomeId },
  })
}

/**
 * Update existing income and adjust ledger/balance
 */
export async function updateIncome(input: UpdateIncomeInput): Promise<Income> {
  // Validate input
  await updateIncomeSchema.validate(input, { abortEarly: false })

  const existing = await getIncomeById(input.id)
  if (!existing) throw new Error(`Income ${input.id} not found`)

  // perform update
  const updated = await prisma.income.update({
    where: { id: input.id },
    data: {
      date: input.date,
      typeId: input.typeId,
      sourceId: input.sourceId,
      accountId: input.accountId,
      amount: toDecimal(input.amount),
      note: input.note,
      assetId: input.assetId,
    },
  })

  // rebuild ledger entries: delete old and create new
  await prisma.ledgerEntry.deleteMany({
    where: { refType: 'INCOME', refId: updated.id },
  })

  const account = await getAccountById(updated.accountId)
  if (!account) throw new Error(`Account ${updated.accountId} not found`)

  await createLedgerEntryTx({
    accountId: updated.accountId,
    direction: 'CREDIT',
    amount: toNumber(updated.amount),
    currency: account.currency,
    refType: 'INCOME',
    refId: updated.id,
    note: `Income: ${updated.note || 'N/A'}`,
  })

  // rebuild balances for old and new account if changed
  if (existing.accountId !== updated.accountId) {
    await prisma.account.update({
      where: { id: existing.accountId },
      data: { balance: await rebuildAccountBalanceFromLedger(existing.accountId) },
    })
  }
  await prisma.account.update({
    where: { id: updated.accountId },
    data: { balance: await rebuildAccountBalanceFromLedger(updated.accountId) },
  })

  return updated
}

/**
 * Helper: rebuild balance dari ledger
 */
async function rebuildAccountBalanceFromLedger(accountId: number): Promise<any> {
  const entries = await prisma.ledgerEntry.findMany({
    where: { accountId },
  })

  let balance = 0
  for (const entry of entries) {
    const amount = toNumber(entry.amount)
    balance = entry.direction === 'CREDIT' ? balance + amount : balance - amount
  }

  return toDecimal(balance)
}
